import{_ as o,o as a,c as t,ag as r}from"./chunks/framework.Pp2klvcf.js";const u=JSON.parse('{"title":"两条架构路径","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/architecture.md","filePath":"zh/guide/architecture.md","lastUpdated":1788681727000}'),c={name:"zh/guide/architecture.md"};function d(i,e,p,n,s,l){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="两条架构路径" tabindex="-1">两条架构路径 <a class="header-anchor" href="#两条架构路径" aria-label="Permalink to &quot;两条架构路径&quot;">​</a></h1><h2 id="polyrepo-在一个应用内切换-ui" tabindex="-1">Polyrepo：在一个应用内切换 UI <a class="header-anchor" href="#polyrepo-在一个应用内切换-ui" aria-label="Permalink to &quot;Polyrepo：在一个应用内切换 UI&quot;">​</a></h2><p><code>config/ui.ts</code> → Vite 别名与 resolver → UI 初始化、主题容器、登录适配、展示适配。页面与状态逻辑保持独立，组件库代码通过构建期选择。</p><p>业务依赖方向是 <code>页面 → Store → API → HTTP</code>。Node 工具在 <code>build/</code>，浏览器运行时代码在 <code>src/</code>，Mock 在 <code>mock/</code>。</p><h2 id="main-应用隔离-共享工程能力" tabindex="-1">Main：应用隔离，共享工程能力 <a class="header-anchor" href="#main-应用隔离-共享工程能力" aria-label="Permalink to &quot;Main：应用隔离，共享工程能力&quot;">​</a></h2><p><code>apps/</code> 放后台与门户；<code>packages/</code> 提供请求、状态、布局、偏好、类型和样式；<code>internal/</code> 提供 Vite/TS/lint 工具；<code>scripts/</code> 提供交互启动和应用脚手架。<code>workspace:*</code> 链接本地包，<code>catalog:</code> 统一依赖版本。</p><p>两条路径都支持多个 UI 生态。差别是隔离单位：polyrepo 通过构建模式隔离，main 通过独立应用隔离。不要把多 UI 共存等同于多个应用，也不要把单应用描述为“没有锁文件、没有规范工具”。</p><p>详见 <a href="/fast-vue3-site/zh/polyrepo/architecture">Polyrepo 架构</a> 与 <a href="/fast-vue3-site/zh/monorepo/architecture">Monorepo 架构</a>。</p>',8)])])}const _=o(c,[["render",d]]);export{u as __pageData,_ as default};
